// === Tab: mySketch ===
// A creative coding sketch heavily inspired by the "Watch Dogs" UI aesthetic,
// now personalized with an integrated logo.

// --- GLOBAL SETTINGS ---
let elements = [];
let logoImg; // This will hold your loaded logo image

// A color palette inspired by the Watch Dogs series' UI.
let palette = {
  background: '#0A141F',
  primary: '#E0E1DD',
  accent: '#415A77',
  highlight: '#778DA9',
  glitch: '#FFFFFF',
  neonGreen: '#91E727', // This matches your logo's background
  tracer: '#00BFFF'
};

// --- P5.JS CORE FUNCTIONS ---

// preload() runs before setup() to ensure all media is loaded.
// IMPORTANT: Add your logo image named "logo.png" to your sketch folder.
function preload() {
  logoImg = loadImage('https://openprocessing.org/sketch/2716544/files/HX-Sports.png');
}

function setup() {
  createCanvas(windowWidth, windowHeight);

  // Start with a busy screen
  for (let i = 0; i < 30; i++) {
    elements.push(getRandomElement());
  }
}

function draw() {
  drawBackground();

  // Randomly add new elements over time.
  if (random(1) < 0.35) {
    elements.push(getRandomElement());
  }

  // Update and display all elements.
  for (let i = elements.length - 1; i >= 0; i--) {
    let el = elements[i];
    el.update();
    el.display();
    if (el.isDead()) {
      elements.splice(i, 1);
    }
  }

  // Draw overlays
  drawMouseGlitch();
  drawScanLines();
}

// --- BACKGROUND & OVERLAY FUNCTIONS ---

function drawBackground() {
  background(palette.background);
  let gridSize = 40;
  strokeWeight(0.5);
  stroke(palette.accent + '33');

  for (let x = 0; x < width; x += gridSize) {
    let offset = sin(frameCount * 0.01 + x * 0.05) * 10;
    line(x + offset, 0, x + offset, height);
  }
  for (let y = 0; y < height; y += gridSize) {
    var offset = cos(frameCount * 0.01 + y * 0.05) * 10;
    line(0, y + offset, width, y + offset);
  }
}

function drawMouseGlitch() {
  let glitchCount = 5;
  for (let i = 0; i < glitchCount; i++) {
    let x1 = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) + random(-25, 25);
    let y1 = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) + random(-25, 25);
    let x2 = x1 + random(-20, 20);
    let y2 = y1 + random(-20, 20);
    stroke(palette.glitch);
    strokeWeight(random(0.5, 1.5));
    line(x1, y1, x2, y2);
  }
}

function drawScanLines() {
  stroke(0, 0, 0, 30);
  strokeWeight(1);
  for (let i = 0; i < height; i += 3) {
    line(0, i, width, i);
  }
}

// --- HELPER FUNCTION ---
function getRandomElement() {
  let type = random(100); // Use a 0-100 scale for probability
  let x = random(width);
  let y = random(height);

  // Use probabilities to control how often each element appears
  if (type < 30) { // 30% chance
    return new DataFragment(x, y);
  } else if (type < 55) { // 25% chance
    return new NetworkNode(x, y);
  } else if (type < 65) { // 10% chance
    let margin = 200;
    return new TargetingReticule(random(margin, width - margin), random(margin, height - margin));
  } else if (type < 75) { // 10% chance
    return new HexagonCluster(x, y);
  } else if (type < 90) { // 15% chance
    return new DataStreamer(x, y);
  } else if (type < 98) { // 8% chance
    return new GlitchLine();
  } else { // 2% chance for a rare logo glitch
    return new LogoGlitch();
  }
}


// --- BASE ELEMENT CLASS (for inheritance) ---
class Element {
  constructor(x, y, lifetime) {
    this.pos = createVector(x, y);
    this.lifetime = lifetime || random(200, 500);
  }
  isDead() { return this.lifetime <= 0; }
  update() { this.lifetime--; }
  display() {}
}


// --- ELEMENT CLASSES ---

/**
 * DataFragment: Small squares of data, some of which are
 * now randomly cropped from the loaded logo image.
 */
class DataFragment extends Element {
  constructor(x, y) {
    super(x, y, random(150, 350));
    this.vel = p5.Vector.random2D().mult(random(0.5, 2));
    this.imageCrop = null;
    this.color = null;

    // 40% chance to be a crop from the logo
    if (random(1) < 0.4) {
      let cropSize = floor(random(15, 40));
      let sx = floor(random(logoImg.width - cropSize));
      let sy = floor(random(logoImg.height - cropSize));
      this.imageCrop = logoImg.get(sx, sy, cropSize, cropSize);
      this.size = cropSize * random(0.8, 1.5);
    } else {
      this.size = random(5, 15);
      this.color = random([palette.primary, palette.accent, palette.neonGreen]);
    }
  }

  update() {
    super.update();
    this.pos.add(this.vel);
    if (this.pos.x < 0 || this.pos.x > width || this.pos.y < 0 || this.pos.y > height) {
      this.lifetime = 0;
    }
  }

  display() {
    let alpha = map(this.lifetime, 0, 100, 0, 255);
    if (this.imageCrop) {
      push();
      // This is a valid use of tint() with grayscale + alpha
      tint(255, alpha);
      image(this.imageCrop, this.pos.x, this.pos.y, this.size, this.size);
      pop();
    } else {
      let c = color(this.color);
      c.setAlpha(alpha);
      fill(c);
      noStroke();
      rect(this.pos.x, this.pos.y, this.size, this.size);
    }
  }
}


/**
 * LogoGlitch: A new class to display the full logo as a rare,
 * heavily distorted and short-lived visual event.
 */
class LogoGlitch extends Element {
    constructor() {
        // Center the glitch and give it a very short lifetime
        super(width / 2, height / 2, random(20, 50));
        this.size = max(width, height) * random(0.5, 0.8);
    }

    display() {
        push();
        var alpha = map(this.lifetime, 0, 20, 0, 150);

        // Randomly offset the image each frame for a shaking effect
        var x = this.pos.x + random(-10, 10);
        var y = this.pos.y + random(-10, 10);

        // --- FIX IS HERE ---
        let tintColor;
        // First, choose which hex string to use
        if (random(1) < 0.5) {
            tintColor = color(palette.neonGreen); // Convert the string to a p5.Color object
        } else {
            tintColor = color(palette.primary);   // Convert the string to a p5.Color object
        }
        // Then, set the alpha on that color object
        tintColor.setAlpha(alpha);

        // Finally, pass the valid p5.Color object to tint()
        tint(tintColor);

        imageMode(CENTER);
        image(logoImg, x, y, this.size, this.size);

        // Draw glitchy rectangles over the logo
        let numGlitches = 10;
        for (let i = 0; i < numGlitches; i++) {
            let gx = x + random(-this.size/2, this.size/2);
            let gy = y + random(-this.size/2, this.size/2);
            let gw = random(10, 100);
            let gh = random(2, 20);
            fill(palette.background);
            noStroke();
            rect(gx, gy, gw, gh);
        }
        pop();
    }
}


// --- OTHER ELEMENT CLASSES (Unchanged from previous version) ---

/**
 * NetworkNode: Static points that connect to other elements.
 */
class NetworkNode extends Element {
  constructor(x, y) {
    super(x, y, random(300, 600));
    this.size = random(4, 8);
    this.color = random([palette.highlight, palette.primary]);
    this.target = null;
    this.connectionCooldown = 20;
  }
  update() {
    super.update();
    this.connectionCooldown--;
    if (!this.target || this.target.isDead() || this.connectionCooldown <= 0) {
      this.findTarget();
    }
    if (this.target && random(1) < 0.01) {
      elements.push(new TracerPacket(this.pos, this.target.pos));
    }
  }
  findTarget() {
    this.connectionCooldown = random(50, 100);
    let potentialTargets = [];
    for (let other of elements) {
      if (other !== this && other.pos) {
        let d = dist(this.pos.x, this.pos.y, other.pos.x, other.pos.y);
        if (d > 0 && d < 200) { potentialTargets.push(other); }
      }
    }
    this.target = random(potentialTargets) || null;
  }
  display() {
    var alpha = map(this.lifetime, 0, 150, 0, 255);
    let nodeColor = color(this.color);
    nodeColor.setAlpha(alpha);
    noStroke();
    fill(nodeColor);
    ellipse(this.pos.x, this.pos.y, this.size, this.size);
    if (this.target) {
      let lineColor = color(this.color);
      lineColor.setAlpha(alpha * 0.5);
      strokeWeight(0.75);
      stroke(lineColor);
      line(this.pos.x, this.pos.y, this.target.pos.x, this.target.pos.y);
    }
  }
}

/**
 * TracerPacket: A visual element that travels along network lines.
 */
class TracerPacket extends Element {
  constructor(startVec, endVec) {
    super(startVec.x, startVec.y, 60);
    this.start = startVec.copy();
    this.end = endVec.copy();
    this.progress = 0;
  }
  update() {
    super.update();
    this.progress = 1 - (this.lifetime / 60);
    this.pos = p5.Vector.lerp(this.start, this.end, this.progress);
  }
  display() {
    noStroke();
    fill(palette.tracer);
    ellipse(this.pos.x, this.pos.y, 5, 5);
  }
}

/**
 * TargetingReticule: A complex, HUD-like targeting graphic.
 */
class TargetingReticule extends Element {
  constructor(x, y) {
    super(x, y, random(250, 600));
    this.maxSize = random(100, 250);
    this.rotationSpeed = random(-0.01, 0.01);
    this.angle = 0;
    this.growth = 0;
  }
  update() {
    super.update();
    this.angle += this.rotationSpeed;
    if (this.growth < this.maxSize) this.growth += 2;
  }
  display() {
    push();
    translate(this.pos.x, this.pos.y);
    rotate(this.angle);
    var alpha = map(this.lifetime, 0, 200, 0, 255);
    let reticuleColor = color(palette.primary);
    reticuleColor.setAlpha(alpha);
    stroke(reticuleColor);
    noFill();
    for (let i = 0; i < 4; i++) {
      strokeWeight(random(0.5, 2));
      let size = this.growth * (i * 0.25 + 0.2);
      let startAngle = random(TWO_PI);
      let endAngle = startAngle + random(PI * 0.5, PI * 1.5);
      arc(0, 0, size, size, startAngle, endAngle);
    }
    let crosshairSize = this.growth / 2;
    strokeWeight(1);
    line(-crosshairSize, 0, -crosshairSize + 20, 0);
    line(crosshairSize, 0, crosshairSize - 20, 0);
    line(0, -crosshairSize, 0, -crosshairSize + 20);
    line(0, crosshairSize, 0, crosshairSize - 20);
    fill(reticuleColor);
    noStroke();
    textSize(10);
    textAlign(CENTER, CENTER);
    text("SCAN", crosshairSize * 0.7, -crosshairSize * 0.7);
    text("ID: " + floor(random(1000, 9999)), -crosshairSize * 0.7, crosshairSize * 0.7);
    pop();
  }
}

/**
 * GlitchLine: A horizontal line that glitches across the screen.
 */
class GlitchLine extends Element {
  constructor() {
    super(0, random(height), random(20, 60));
    this.height = random(1, 4);
  }
  update() {
    super.update();
    if (random(1) < 0.1) this.pos.y = random(height);
  }
  display() {
    var alpha = map(this.lifetime, 0, 20, 0, 150);
    let glitchColor = color(palette.glitch);
    glitchColor.setAlpha(alpha);
    fill(glitchColor);
    noStroke();
    var x = random(-50, 50);
    let w = width + random(-100, 100);
    rect(x, this.pos.y, w, this.height);
  }
}

/**
 * HexagonCluster: A pulsing group of hexagons.
 */
class HexagonCluster extends Element {
  constructor(x, y) {
    super(x, y, random(300, 700));
    this.size = random(20, 50);
    this.numHex = floor(random(3, 7));
    this.angle = random(TWO_PI);
  }
  update() {
    super.update();
    this.angle += 0.005;
  }
  display() {
    push();
    translate(this.pos.x, this.pos.y);
    rotate(this.angle);
    var alpha = map(this.lifetime, 0, 100, 0, 255);
    let pulse = map(sin(frameCount * 0.05), -1, 1, 50, 255);
    let hexColor = color(palette.highlight);
    hexColor.setAlpha(alpha * (pulse / 255));
    stroke(hexColor);
    strokeWeight(1.5);
    noFill();
    this._drawHex(0, 0, this.size);
    for (let i = 0; i < this.numHex; i++) {
      let a = TWO_PI / 6 * i;
      var x = cos(a) * this.size * 1.75;
      var y = sin(a) * this.size * 1.75;
      this._drawHex(x, y, this.size);
    }
    pop();
  }
  _drawHex(x, y, radius) {
    beginShape();
    for (let i = 0; i < 6; i++) {
      let angle = TWO_PI / 6 * i;
      let vx = x + cos(angle) * radius;
      let vy = y + sin(angle) * radius;
      vertex(vx, vy);
    }
    endShape(CLOSE);
  }
}

/**
 * DataStreamer: A line of text that appears to be typing out.
 */
class DataStreamer extends Element {
  constructor(x, y) {
    super(x, y, random(150, 400));
    this.text = this._generateRandomText(floor(random(20, 40)));
    this.revealedLength = 0;
  }
  update() {
    super.update();
    if (this.revealedLength < this.text.length) {
      this.revealedLength += 0.5;
    }
  }
  display() {
    var alpha = map(this.lifetime, 0, 50, 0, 255);
    let textColor = color(palette.neonGreen);
    textColor.setAlpha(alpha);
    fill(textColor);
    noStroke();
    textSize(12);
    textFont('monospace');
    textAlign(LEFT, TOP);
    text(this.text.substring(0, this.revealedLength), this.pos.x, this.pos.y);
  }
  _generateRandomText(len) {
    let chars = '0123456789ABCDEF';
    let result = '0x';
    for (let i = 0; i < len; i++) {
      result += chars.charAt(floor(random(chars.length)));
    }
    return result;
  }
}

// --- BROWSER WINDOW RESIZING ---
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

